// src/App.tsx
import React from 'react';
import { BrowserRouter } from 'react-router-dom';
import { Provider } from 'react-redux';
import { PersistGate } from 'redux-persist/integration/react';
import { Toaster } from 'react-hot-toast';
import { store, persistor } from './store';
import { AppRoutes } from './app/routes/AppRoutes';

// ==========================
// PAGE LOADER
// ==========================
const PageLoader = () => (
  <div className="flex items-center justify-center min-h-screen bg-[#030508]">
    <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-cyan-500" />
  </div>
);

// ==========================
// ROOT APP
// ==========================
function App() {
  return (
    <Provider store={store}>
      <PersistGate loading={<PageLoader />} persistor={persistor}>
        <BrowserRouter>
          <Toaster
            position="top-right"
            toastOptions={{
              style: {
                background: '#1e293b',
                color: '#fff',
                border: '1px solid rgba(255,255,255,0.1)',
              },
            }}
          />
          <AppRoutes />
        </BrowserRouter>
      </PersistGate>
    </Provider>
  );
}

export default App;

// src/components/ProtectedRoute.tsx
import { Navigate, Outlet, useLocation } from 'react-router-dom';
import { useAppSelector } from 'src/store';  // ✅ পাথ ঠিক করা হয়েছে

// Optional: Add role-based protection
interface ProtectedRouteProps {
  allowedRoles?: string[];  // নতুন: রোল বেসড অ্যাক্সেস
  redirectTo?: string;       // নতুন: কাস্টম রিডাইরেক্ট
}

const ProtectedRoute = ({ allowedRoles, redirectTo = '/login' }: ProtectedRouteProps = {}) => {
  const { isAuthenticated, isLoading, user } = useAppSelector((state) => state.auth);
  const location = useLocation();

  // Show loading while checking authentication
  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-4 border-blue-500 border-t-transparent"></div>
      </div>
    );
  }

  // If not authenticated, redirect to login
  if (!isAuthenticated) {
    return <Navigate to={redirectTo} state={{ from: location.pathname }} replace />;
  }

  // Optional: Check if user has required role
  if (allowedRoles && allowedRoles.length > 0) {
    const userRole = user?.primaryRole || user?.role;
    if (!userRole || !allowedRoles.includes(userRole)) {
      // User doesn't have required role, redirect to home page
      return <Navigate to="/" replace />;
    }
  }

  // If authenticated, render the child routes
  return <Outlet />;
};

export default ProtectedRoute;

// src/app/routes/AppRoutes.tsx
import React, { Suspense } from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import { useSelector } from 'react-redux';
import { routeConfig, type RouteItem } from './routeConfig';
import type { RootState } from '../../store';

// ============================================
// PAGE LOADER
// ============================================
const PageLoader: React.FC = () => (
  <div className="flex items-center justify-center min-h-screen bg-[#030508]">
    <div className="flex flex-col items-center gap-4">
      <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-cyan-500" />
      <p className="text-white/30 text-sm">Loading...</p>
    </div>
  </div>
);

// ============================================
// AUTH GUARD
// ============================================
const AuthGuard: React.FC<{ route: RouteItem; children: React.ReactNode }> = ({ route, children }) => {
  const auth = useSelector((state: RootState) => state.auth);
  const sessionToken = sessionStorage.getItem('auth_token');
  const userRole = sessionStorage.getItem('user_role');

  const isAuthenticated = auth?.isAuthenticated && sessionToken;

  // Not logged in
  if (!isAuthenticated) {
    return <Navigate to="/login" replace />;
  }

  // Wrong role
  if (route.roles && !route.roles.includes(userRole || '')) {
    return <Navigate to="/" replace />;
  }

  return <>{children}</>;
};

// ============================================
// PUBLIC GUARD
// ============================================
const PublicGuard: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const auth = useSelector((state: RootState) => state.auth);
  const sessionToken = sessionStorage.getItem('auth_token');
  const userRole = sessionStorage.getItem('user_role');

  if (auth?.isAuthenticated && sessionToken && userRole) {
    return <Navigate to={`/${userRole}/dashboard`} replace />;
  }

  return <>{children}</>;
};

// ============================================
// HOSPITAL DETAILS WRAPPER
// ============================================
import HospitalDetails from '../../components/hospital/EmergencyServices';

const HospitalDetailsWrapper: React.FC = () => (
  <HospitalDetails
    icuBeds={{ total: 50, available: 15, occupied: 35, covid: 10, nonCovid: 25, emergency: 5, cardiac: 8, pediatric: 5, neonatal: 2 }}
    resources={[]}
    staff={[]}
  />
);

// ============================================
// MAIN ROUTES
// ============================================
export const AppRoutes: React.FC = () => {
  return (
    <Suspense fallback={<PageLoader />}>
      <Routes>
        {routeConfig.map((route) => {
          const Component = route.component;

          // Special case for hospital/:id with props
          if (route.path === '/hospital/:id') {
            return (
              <Route
                key={route.path}
                path={route.path}
                element={<HospitalDetailsWrapper />}
              />
            );
          }

          // Protected routes
          if (route.isProtected) {
            return (
              <Route
                key={route.path}
                path={route.path}
                element={
                  <AuthGuard route={route}>
                    <Component />
                  </AuthGuard>
                }
              />
            );
          }

          // Login/Register - redirect if already logged in
          if (route.path === '/login' || route.path === '/register') {
            return (
              <Route
                key={route.path}
                path={route.path}
                element={
                  <PublicGuard>
                    <Component />
                  </PublicGuard>
                }
              />
            );
          }

          // Public routes
          return (
            <Route
              key={route.path}
              path={route.path}
              element={<Component />}
            />
          );
        })}
      </Routes>
    </Suspense>
  );
};

