// src/store/index.ts
import { configureStore, combineReducers } from "@reduxjs/toolkit";
import { TypedUseSelectorHook, useDispatch, useSelector } from "react-redux";
import {
  persistStore,
  persistReducer,
  FLUSH,
  REHYDRATE,
  PAUSE,
  PERSIST,
  PURGE,
  REGISTER,
} from "redux-persist";
import storage from "redux-persist/lib/storage";

// ============================================
// SLICES
// ============================================
import authReducer from "./slices/authSlice";
import clientReducer from "./slices/clientSlice";
import doctorReducer from "./slices/DoctorSlice";
import hospitalReducer from "./slices/hospitalSlice";
import appointmentReducer from "./slices/appointmentSlice";
import emergencyReducer from "./slices/emergencySlice";
import pharmacyReducer from "./slices/pharmacySlice";
import adminReducer from "./slices/adminSlice";
import uiReducer from "./slices/uiSlice";

// ============================================
// PERSIST CONFIG
// ============================================
const persistConfig = {
  key: "root",
  version: 1,
  storage,
  whitelist: ["client", "doctor", "hospital", "appointment", "emergency", "pharmacy", "admin", "ui"],
};

// ============================================
// ROOT REDUCER
// ============================================
const rootReducer = combineReducers({
  auth: authReducer,
  client: clientReducer,
  doctor: doctorReducer,
  hospital: hospitalReducer,
  appointment: appointmentReducer,
  emergency: emergencyReducer,
  pharmacy: pharmacyReducer,
  admin: adminReducer,
  ui: uiReducer,
});

const persistedReducer = persistReducer(persistConfig, rootReducer);

// ============================================
// STORE
// ============================================
export const store = configureStore({
  reducer: persistedReducer,

  middleware: (getDefaultMiddleware) =>
    getDefaultMiddleware({
      serializableCheck: {
        ignoredActions: [FLUSH, REHYDRATE, PAUSE, PERSIST, PURGE, REGISTER],
      },
    }),

  devTools: import.meta.env.DEV,
});

export const persistor = persistStore(store);

// ============================================
// TYPES
// ============================================
export type RootState = ReturnType<typeof rootReducer>;
export type AppDispatch = typeof store.dispatch;

// ============================================
// HOOKS - FIXED
// ============================================
export const useAppDispatch: () => AppDispatch = useDispatch;
export const useAppSelector: TypedUseSelectorHook<RootState> = useSelector;

// Default export
export default store;

// src/store/slices/authSlice.ts
// AUTHENTICATION + MULTI-ROLE MANAGEMENT (No Data Save)

import { createSlice, PayloadAction, createAsyncThunk } from '@reduxjs/toolkit';

// ============================================
// TYPES
// ============================================

export type AccountRole = 'normal_user' | 'client' | 'doctor' | 'hospital' | 'hospital_admin' | 'hospital_authority' | 'pharmacy' | 'pharmacy_admin' | 'admin' | 'admin_applicant' | 'blood_donor' | 'emergency_volunteer';

export type ProfileUpgrade = 'client_patient' | 'blood_donor' | 'pharmacy_user' | 'emergency_volunteer';

export interface User {
  id: string;
  name?: string;
  fullName?: string;
  email: string;
  phone?: string;
  bloodGroup?: string;
  gender?: 'male' | 'female' | 'other';
  profileImage?: string;
  role?: AccountRole;
  
  // Multi-role support
  roles: AccountRole[];           // All roles user has
  primaryRole: AccountRole;       // Current active role
  upgrades: ProfileUpgrade[];     // Profile upgrades
  
  // Status
  isVerified?: boolean;
  isAdminApproved?: boolean;
  isActive?: boolean;
  isOnline?: boolean;
  
  // Timestamps
  createdAt: string;
  updatedAt?: string;
  lastLogin?: string;
  
  // ❌ Token সরানো হয়েছে - কোন ডাটা সেভ হবে না
  // token?: string;
  [key: string]: unknown;
}

export interface AuthState {
  user: User | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  error: string | null;
}

// ============================================
// INITIAL STATE
// ============================================

const initialState: AuthState = {
  user: null,
  isAuthenticated: false,
  isLoading: false,
  error: null,
};

// ============================================
// ASYNC THUNKS - localStorage সরানো হয়েছে
// ============================================

// ✅ Login thunk - কোন ডাটা সেভ করে না
export const loginUser = createAsyncThunk(
  'auth/loginUser',
  async ({ email, password }: { email: string; password: string }) => {
    // সিমুলেটেড API কল
    await new Promise(resolve => setTimeout(resolve, 1000));
    
    if (!email || !password) {
      throw new Error('Email and password required');
    }
    
    // টেম্পোরারি ইউজার - শুধু মেমোরিতে থাকবে
    const mockUser: User = {
      id: `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      name: email.split('@')[0],
      fullName: email.split('@')[0],
      email: email,
      role: 'client',
      roles: ['client', 'normal_user'],
      primaryRole: 'client',
      upgrades: [],
      isVerified: true,
      isActive: true,
      createdAt: new Date().toISOString(),
    };
    
    // ❌ localStorage.setItem সরানো হয়েছে
    return mockUser;
  }
);

// ✅ Register thunk - কোন ডাটা সেভ করে না
export const registerUser = createAsyncThunk(
  'auth/registerUser',
  async (userData: Partial<User> & { password: string }) => {
    await new Promise(resolve => setTimeout(resolve, 1000));
    
    const mockUser: User = {
      id: `session_${Date.now()}`,
      name: userData.name || userData.email?.split('@')[0] || 'User',
      email: userData.email || '',
      role: 'client',
      roles: ['client', 'normal_user'],
      primaryRole: 'client',
      upgrades: [],
      isVerified: true,
      isActive: true,
      createdAt: new Date().toISOString(),
    };
    
    // ❌ localStorage.setItem সরানো হয়েছে
    return mockUser;
  }
);

// ✅ Logout thunk - localStorage পরিষ্কার করার দরকার নেই
export const logoutUser = createAsyncThunk('auth/logoutUser', async () => {
  await new Promise(resolve => setTimeout(resolve, 500));
  // ❌ localStorage.removeItem সরানো হয়েছে
  return null;
});

// ❌ getCurrentUser সম্পূর্ণ সরিয়ে দেওয়া হয়েছে - কারণ কোন ডাটা সেভ নেই
// export const getCurrentUser = createAsyncThunk(...) - এই পুরো অংশ ডিলিট করুন

// ============================================
// SLICE
// ============================================

const authSlice = createSlice({
  name: 'auth',
  initialState,
  reducers: {
    loginStart: (state) => {
      state.isLoading = true;
      state.error = null;
    },
    loginSuccess: (state, action: PayloadAction<User>) => {
      state.isLoading = false;
      state.isAuthenticated = true;
      state.user = action.payload;
      state.error = null;
    },
    login: (state, action: PayloadAction<User>) => {
      state.isLoading = false;
      state.isAuthenticated = true;
      state.user = action.payload;
      state.error = null;
    },
    loginFailure: (state, action: PayloadAction<string>) => {
      state.isLoading = false;
      state.error = action.payload;
    },

    logout: (state) => {
      state.user = null;
      state.isAuthenticated = false;
      state.isLoading = false;
      state.error = null;
      // ❌ localStorage.removeItem('token'); সরানো হয়েছে
    },

    updateProfile: (state, action: PayloadAction<Partial<User>>) => {
      if (state.user) {
        state.user = { ...state.user, ...action.payload };
      }
    },
    
    // Multi-role management
    addRole: (state, action: PayloadAction<AccountRole>) => {
      if (state.user && !state.user.roles.includes(action.payload)) {
        state.user.roles.push(action.payload);
      }
    },
    removeRole: (state, action: PayloadAction<AccountRole>) => {
      if (state.user) {
        state.user.roles = state.user.roles.filter(r => r !== action.payload);
        if (state.user.primaryRole === action.payload) {
          state.user.primaryRole = state.user.roles[0] || 'normal_user';
        }
      }
    },
    setPrimaryRole: (state, action: PayloadAction<AccountRole>) => {
      if (state.user && state.user.roles.includes(action.payload)) {
        state.user.primaryRole = action.payload;
      }
    },
    addUpgrade: (state, action: PayloadAction<ProfileUpgrade>) => {
      if (state.user && !state.user.upgrades.includes(action.payload)) {
        state.user.upgrades.push(action.payload);
      }
    },
    removeUpgrade: (state, action: PayloadAction<ProfileUpgrade>) => {
      if (state.user) {
        state.user.upgrades = state.user.upgrades.filter(u => u !== action.payload);
      }
    },
    switchRole: (state, action: PayloadAction<AccountRole>) => {
      if (state.user && state.user.roles.includes(action.payload)) {
        state.user.primaryRole = action.payload;
      }
    },
    setOnlineStatus: (state, action: PayloadAction<boolean>) => {
      if (state.user) {
        state.user.isOnline = action.payload;
      }
    },
    clearError: (state) => {
      state.error = null;
    },
    setLoading: (state, action: PayloadAction<boolean>) => {
      state.isLoading = action.payload;
    },
  },
  
  extraReducers: (builder) => {
    builder
      // Login User
      .addCase(loginUser.pending, (state) => {
        state.isLoading = true;
        state.error = null;
      })
      .addCase(loginUser.fulfilled, (state, action) => {
        state.isLoading = false;
        state.isAuthenticated = true;
        state.user = action.payload;
        state.error = null;
      })
      .addCase(loginUser.rejected, (state, action) => {
        state.isLoading = false;
        state.error = action.error.message || 'Login failed';
      })
      // Register User
      .addCase(registerUser.pending, (state) => {
        state.isLoading = true;
        state.error = null;
      })
      .addCase(registerUser.fulfilled, (state, action) => {
        state.isLoading = false;
        state.isAuthenticated = true;
        state.user = action.payload;
        state.error = null;
      })
      .addCase(registerUser.rejected, (state, action) => {
        state.isLoading = false;
        state.error = action.error.message || 'Registration failed';
      })
      // Logout User
      .addCase(logoutUser.fulfilled, (state) => {
        state.user = null;
        state.isAuthenticated = false;
        state.isLoading = false;
        state.error = null;
      });
      // ❌ getCurrentUser এর কেসগুলি সরানো হয়েছে
  },
});

// ============================================
// SELECTORS
// ============================================

export const selectUser = (state: { auth: AuthState }) => state.auth.user;
export const selectIsAuthenticated = (state: { auth: AuthState }) => state.auth.isAuthenticated;
export const selectIsLoading = (state: { auth: AuthState }) => state.auth.isLoading;
export const selectAuthError = (state: { auth: AuthState }) => state.auth.error;
export const selectUserRoles = (state: { auth: AuthState }) => state.auth.user?.roles || [];
export const selectPrimaryRole = (state: { auth: AuthState }) => state.auth.user?.primaryRole || 'normal_user';
export const selectUserUpgrades = (state: { auth: AuthState }) => state.auth.user?.upgrades || [];

// ============================================
// EXPORTS
// ============================================

export const {
  loginStart,
  login,
  loginSuccess,
  loginFailure,
  logout,
  updateProfile,
  addRole,
  removeRole,
  setPrimaryRole,
  addUpgrade,
  removeUpgrade,
  switchRole,
  setOnlineStatus,
  clearError,
  setLoading,
} = authSlice.actions;

export default authSlice.reducer;

// src/store/slices/clientSlice.ts
import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import {
  ClientProfile,
  Appointment,
  BloodDonation,
  HealthRecommendation,
  MedicineReminder,
  EmergencyRequest,
  HealthStats,
  Prescription,
  MedicalReport,
  HealthTimelineEvent,
} from '../../types/client';

interface ClientState {
  profile: ClientProfile | null;
  appointments: Appointment[];
  bloodDonations: BloodDonation[];
  recommendations: HealthRecommendation[];
  reminders: MedicineReminder[];
  emergencyRequests: EmergencyRequest[];
  prescriptions: Prescription[];
  reports: MedicalReport[];
  timeline: HealthTimelineEvent[];
  stats: HealthStats;
  isLoading: boolean;
}

const initialState: ClientState = {
  profile: null,
  appointments: [],
  bloodDonations: [],
  recommendations: [],
  reminders: [],
  emergencyRequests: [],
  prescriptions: [],
  reports: [],
  timeline: [],
  stats: {
    upcomingAppointments: 0,
    activePrescriptions: 0,
    bloodDonations: 0,
    medicalReports: 0,
    healthScore: 85,
  },
  isLoading: false,
};

const clientSlice = createSlice({
  name: 'client',
  initialState,
  reducers: {
    setProfile: (state, action: PayloadAction<ClientProfile>) => {
      state.profile = action.payload;
    },
    updateProfile: (state, action: PayloadAction<Partial<ClientProfile>>) => {
      if (state.profile) {
        state.profile = { ...state.profile, ...action.payload };
      }
    },
    setAppointments: (state, action: PayloadAction<Appointment[]>) => {
      state.appointments = action.payload;
      state.stats.upcomingAppointments = action.payload.filter(
        a => a.status === 'upcoming'
      ).length;
    },
    addAppointment: (state, action: PayloadAction<Appointment>) => {
      state.appointments.unshift(action.payload);
      state.stats.upcomingAppointments++;
    },
    updateAppointment: (state, action: PayloadAction<Appointment>) => {
      const index = state.appointments.findIndex(a => a.id === action.payload.id);
      if (index !== -1) {
        state.appointments[index] = action.payload;
      }
    },
    setBloodDonations: (state, action: PayloadAction<BloodDonation[]>) => {
      state.bloodDonations = action.payload;
      state.stats.bloodDonations = action.payload.length;
    },
    addBloodDonation: (state, action: PayloadAction<BloodDonation>) => {
      state.bloodDonations.unshift(action.payload);
      state.stats.bloodDonations++;
    },
    setRecommendations: (state, action: PayloadAction<HealthRecommendation[]>) => {
      state.recommendations = action.payload;
    },
    setReminders: (state, action: PayloadAction<MedicineReminder[]>) => {
      state.reminders = action.payload;
      state.stats.activePrescriptions = action.payload.filter(r => r.isActive).length;
    },
    addReminder: (state, action: PayloadAction<MedicineReminder>) => {
      state.reminders.push(action.payload);
      state.stats.activePrescriptions++;
    },
    toggleReminder: (state, action: PayloadAction<string>) => {
      const reminder = state.reminders.find(r => r.id === action.payload);
      if (reminder) {
        reminder.isActive = !reminder.isActive;
        state.stats.activePrescriptions = state.reminders.filter(r => r.isActive).length;
      }
    },
    setEmergencyRequests: (state, action: PayloadAction<EmergencyRequest[]>) => {
      state.emergencyRequests = action.payload;
    },
    addEmergencyRequest: (state, action: PayloadAction<EmergencyRequest>) => {
      state.emergencyRequests.unshift(action.payload);
    },
    setPrescriptions: (state, action: PayloadAction<Prescription[]>) => {
      state.prescriptions = action.payload;
    },
    setReports: (state, action: PayloadAction<MedicalReport[]>) => {
      state.reports = action.payload;
      state.stats.medicalReports = action.payload.length;
    },
    addReport: (state, action: PayloadAction<MedicalReport>) => {
      state.reports.unshift(action.payload);
      state.stats.medicalReports++;
    },
    setTimeline: (state, action: PayloadAction<HealthTimelineEvent[]>) => {
      state.timeline = action.payload;
    },
    setStats: (state, action: PayloadAction<HealthStats>) => {
      state.stats = action.payload;
    },
    setLoading: (state, action: PayloadAction<boolean>) => {
      state.isLoading = action.payload;
    },
  },
});

export const {
  setProfile,
  updateProfile,
  setAppointments,
  addAppointment,
  updateAppointment,
  setBloodDonations,
  addBloodDonation,
  setRecommendations,
  setReminders,
  addReminder,
  toggleReminder,
  setEmergencyRequests,
  addEmergencyRequest,
  setPrescriptions,
  setReports,
  addReport,
  setTimeline,
  setStats,
  setLoading,
} = clientSlice.actions;

export default clientSlice.reducer;

