  phone?: string;
  bloodGroup?: string;
  gender?: 'male' | 'female' | 'other';
  profileImage?: string;
  role?: AccountRole;
  
  // Multi-role support
  roles: AccountRole[];           // All roles user has
  primaryRole: AccountRole;       // Current active role
  upgrades: ProfileUpgrade[];     // Profile upgrades
  
  // Status
  isVerified?: boolean;
  isAdminApproved?: boolean;
  isActive?: boolean;
  isOnline?: boolean;
  
  // Timestamps
  createdAt: string;
  updatedAt?: string;
  lastLogin?: string;
  
  // ❌ Token সরানো হয়েছে - কোন ডাটা সেভ হবে না
  // token?: string;
  [key: string]: unknown;
}

export interface AuthState {
  user: User | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  error: string | null;
}

// ============================================
// INITIAL STATE
// ============================================

const initialState: AuthState = {
  user: null,
  isAuthenticated: false,
  isLoading: false,
  error: null,
};

// ============================================
// ASYNC THUNKS - localStorage সরানো হয়েছে
// ============================================

// ✅ Login thunk - কোন ডাটা সেভ করে না
export const loginUser = createAsyncThunk(
  'auth/loginUser',
  async ({ email, password }: { email: string; password: string }) => {
    // সিমুলেটেড API কল
    await new Promise(resolve => setTimeout(resolve, 1000));
    
    if (!email || !password) {
      throw new Error('Email and password required');
    }
    
    // টেম্পোরারি ইউজার - শুধু মেমোরিতে থাকবে
    const mockUser: User = {
      id: `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      name: email.split('@')[0],
      fullName: email.split('@')[0],
      email: email,
      role: 'client',
      roles: ['client', 'normal_user'],
      primaryRole: 'client',
      upgrades: [],
      isVerified: true,
      isActive: true,
      createdAt: new Date().toISOString(),
    };
    
    // ❌ localStorage.setItem সরানো হয়েছে
    return mockUser;
  }
);

// ✅ Register thunk - কোন ডাটা সেভ করে না
export const registerUser = createAsyncThunk(
  'auth/registerUser',
  async (userData: Partial<User> & { password: string }) => {
    await new Promise(resolve => setTimeout(resolve, 1000));
    
    const mockUser: User = {
      id: `session_${Date.now()}`,
      name: userData.name || userData.email?.split('@')[0] || 'User',
      email: userData.email || '',
      role: 'client',
      roles: ['client', 'normal_user'],
      primaryRole: 'client',
      upgrades: [],
      isVerified: true,
      isActive: true,
      createdAt: new Date().toISOString(),
    };
    
    // ❌ localStorage.setItem সরানো হয়েছে
    return mockUser;
  }
);

// ✅ Logout thunk - localStorage পরিষ্কার করার দরকার নেই
export const logoutUser = createAsyncThunk('auth/logoutUser', async () => {
  await new Promise(resolve => setTimeout(resolve, 500));
  // ❌ localStorage.removeItem সরানো হয়েছে
  return null;
});

// ❌ getCurrentUser সম্পূর্ণ সরিয়ে দেওয়া হয়েছে - কারণ কোন ডাটা সেভ নেই
// export const getCurrentUser = createAsyncThunk(...) - এই পুরো অংশ ডিলিট করুন

// ============================================
// SLICE
// ============================================

const authSlice = createSlice({
  name: 'auth',
  initialState,
  reducers: {
    loginStart: (state) => {
      state.isLoading = true;
      state.error = null;
    },
    loginSuccess: (state, action: PayloadAction<User>) => {
      state.isLoading = false;
      state.isAuthenticated = true;
      state.user = action.payload;
      state.error = null;
    },
    login: (state, action: PayloadAction<User>) => {
      state.isLoading = false;
      state.isAuthenticated = true;
      state.user = action.payload;
      state.error = null;
    },
    loginFailure: (state, action: PayloadAction<string>) => {
      state.isLoading = false;
      state.error = action.payload;
    },

    logout: (state) => {
      state.user = null;
      state.isAuthenticated = false;
      state.isLoading = false;
      state.error = null;
      // ❌ localStorage.removeItem('token'); সরানো হয়েছে
    },

    updateProfile: (state, action: PayloadAction<Partial<User>>) => {
      if (state.user) {
        state.user = { ...state.user, ...action.payload };
      }
    },
    
    // Multi-role management
    addRole: (state, action: PayloadAction<AccountRole>) => {
      if (state.user && !state.user.roles.includes(action.payload)) {
        state.user.roles.push(action.payload);
      }
    },
    removeRole: (state, action: PayloadAction<AccountRole>) => {
      if (state.user) {
        state.user.roles = state.user.roles.filter(r => r !== action.payload);
        if (state.user.primaryRole === action.payload) {
          state.user.primaryRole = state.user.roles[0] || 'normal_user';
        }
      }
    },
    setPrimaryRole: (state, action: PayloadAction<AccountRole>) => {
      if (state.user && state.user.roles.includes(action.payload)) {
        state.user.primaryRole = action.payload;
      }
    },
    addUpgrade: (state, action: PayloadAction<ProfileUpgrade>) => {
      if (state.user && !state.user.upgrades.includes(action.payload)) {
        state.user.upgrades.push(action.payload);
      }
    },
    removeUpgrade: (state, action: PayloadAction<ProfileUpgrade>) => {
      if (state.user) {
        state.user.upgrades = state.user.upgrades.filter(u => u !== action.payload);
      }
    },
    switchRole: (state, action: PayloadAction<AccountRole>) => {
      if (state.user && state.user.roles.includes(action.payload)) {
        state.user.primaryRole = action.payload;
      }
    },
    setOnlineStatus: (state, action: PayloadAction<boolean>) => {
      if (state.user) {
        state.user.isOnline = action.payload;
      }
    },
    clearError: (state) => {
      state.error = null;
    },
    setLoading: (state, action: PayloadAction<boolean>) => {
      state.isLoading = action.payload;
    },
  },
  
  extraReducers: (builder) => {
    builder
      // Login User
      .addCase(loginUser.pending, (state) => {
        state.isLoading = true;
        state.error = null;
      })
      .addCase(loginUser.fulfilled, (state, action) => {
        state.isLoading = false;
        state.isAuthenticated = true;
        state.user = action.payload;
        state.error = null;
      })
      .addCase(loginUser.rejected, (state, action) => {
        state.isLoading = false;
        state.error = action.error.message || 'Login failed';
      })
      // Register User
      .addCase(registerUser.pending, (state) => {
        state.isLoading = true;
        state.error = null;
      })
      .addCase(registerUser.fulfilled, (state, action) => {
        state.isLoading = false;
        state.isAuthenticated = true;
        state.user = action.payload;
        state.error = null;
      })
      .addCase(registerUser.rejected, (state, action) => {
        state.isLoading = false;
        state.error = action.error.message || 'Registration failed';
      })
      // Logout User
      .addCase(logoutUser.fulfilled, (state) => {
        state.user = null;
        state.isAuthenticated = false;
        state.isLoading = false;
        state.error = null;
      });
      // ❌ getCurrentUser এর কেসগুলি সরানো হয়েছে
  },
});

// ============================================
// SELECTORS
// ============================================

export const selectUser = (state: { auth: AuthState }) => state.auth.user;
export const selectIsAuthenticated = (state: { auth: AuthState }) => state.auth.isAuthenticated;
export const selectIsLoading = (state: { auth: AuthState }) => state.auth.isLoading;
export const selectAuthError = (state: { auth: AuthState }) => state.auth.error;
export const selectUserRoles = (state: { auth: AuthState }) => state.auth.user?.roles || [];
export const selectPrimaryRole = (state: { auth: AuthState }) => state.auth.user?.primaryRole || 'normal_user';
export const selectUserUpgrades = (state: { auth: AuthState }) => state.auth.user?.upgrades || [];

// ============================================
// EXPORTS
// ============================================

export const {
  loginStart,
  login,
  loginSuccess,
  loginFailure,
  logout,
  updateProfile,
  addRole,
  removeRole,
  setPrimaryRole,
  addUpgrade,
  removeUpgrade,
  switchRole,
  setOnlineStatus,
  clearError,
  setLoading,
} = authSlice.actions;

export default authSlice.reducer;

// ============================================
// src/store/slices/appointmentSlice.ts
// Aetherion Health - Appointment Redux Slice
// ============================================

import { createSlice, createAsyncThunk, PayloadAction } from '@reduxjs/toolkit';

// ============================================
// TYPES
// ============================================

export interface Appointment {
  id: string;
  patientId: string;
  patientName: string;
  doctorId: string;
  doctorName: string;
  doctorSpecialty: string;
  hospitalName: string;
  date: string;
  time: string;
  type: 'in-person' | 'video' | 'phone';
  status: 'scheduled' | 'confirmed' | 'in-progress' | 'completed' | 'cancelled' | 'no-show';
  reason: string;
  notes?: string;
  prescriptionId?: string;
  followUpDate?: string;
  amount: number;
  paymentStatus: 'pending' | 'paid' | 'refunded' | 'insurance';
  createdAt: string;
  updatedAt: string;
}

interface AppointmentState {
  appointments: Appointment[];
  selectedAppointment: Appointment | null;
  isLoading: boolean;
  error: string | null;
  filters: {
    status: string;
    type: string;
    date: string;
    search: string;
  };
  stats: {
    total: number;
    scheduled: number;
    completed: number;
    cancelled: number;
    todayCount: number;
  };
  pagination: {
    page: number;
    limit: number;
    total: number;
  };
}

// ============================================
// INITIAL STATE
// ============================================

const initialState: AppointmentState = {
  appointments: [],
  selectedAppointment: null,
  isLoading: false,
  error: null,
  filters: {
    status: 'all',
    type: 'all',
    date: '',
    search: '',
  },
  stats: {
    total: 0,
    scheduled: 0,
    completed: 0,
    cancelled: 0,
    todayCount: 0,
  },
  pagination: {
    page: 1,
    limit: 10,
    total: 0,
  },
};

// ============================================
// ASYNC THUNKS
// ============================================

// Fetch all appointments
export const fetchAppointments = createAsyncThunk(
  'appointments/fetchAll',
  async (params: { page?: number; limit?: number; status?: string } | undefined, { rejectWithValue }) => {
    try {
      // TODO: Replace with actual API call
      // const response = await api.get('/appointments', { params });
      // return response.data;
      
      // Mock data for now
      return {
        appointments: [],
        pagination: { page: 1, limit: 10, total: 0 },
      };
    } catch (error: any) {
      return rejectWithValue(error.message || 'Failed to fetch appointments');
    }
  }
);

// Book new appointment
export const bookAppointment = createAsyncThunk(
  'appointments/book',
  async (appointmentData: Partial<Appointment>, { rejectWithValue }) => {
    try {
      // TODO: Replace with actual API call
      // const response = await api.post('/appointments', appointmentData);
      // return response.data;
      
      return {
        ...appointmentData,
        id: Date.now().toString(),
        status: 'scheduled',
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      } as Appointment;
    } catch (error: any) {
      return rejectWithValue(error.message || 'Failed to book appointment');
    }
  }
);

// Cancel appointment
export const cancelAppointment = createAsyncThunk(
  'appointments/cancel',
  async (id: string, { rejectWithValue }) => {
    try {
      // TODO: Replace with actual API call
      // await api.put(`/appointments/${id}/cancel`);
      return id;
    } catch (error: any) {
      return rejectWithValue(error.message || 'Failed to cancel appointment');
    }
  }
);

// Reschedule appointment
export const rescheduleAppointment = createAsyncThunk(
  'appointments/reschedule',
  async ({ id, date, time }: { id: string; date: string; time: string }, { rejectWithValue }) => {
    try {
      // TODO: Replace with actual API call
      // const response = await api.put(`/appointments/${id}/reschedule`, { date, time });
      // return response.data;
      
      return { id, date, time };
    } catch (error: any) {
      return rejectWithValue(error.message || 'Failed to reschedule appointment');
    }
  }
);

// ============================================
// APPOINTMENT SLICE
// ============================================

const appointmentSlice = createSlice({
  name: 'appointments',
  initialState,
  reducers: {
    // Select appointment
    setSelectedAppointment: (state, action: PayloadAction<Appointment | null>) => {
      state.selectedAppointment = action.payload;
    },

    // Clear selection
    clearSelectedAppointment: (state) => {
      state.selectedAppointment = null;
    },

    // Set filters
    setFilters: (state, action: PayloadAction<Partial<AppointmentState['filters']>>) => {
      state.filters = { ...state.filters, ...action.payload };
    },

    // Reset filters
    resetFilters: (state) => {
      state.filters = initialState.filters;
    },

    // Set page
    setPage: (state, action: PayloadAction<number>) => {
      state.pagination.page = action.payload;
    },

    // Update appointment status locally
    updateAppointmentStatus: (state, action: PayloadAction<{ id: string; status: Appointment['status'] }>) => {
      const appointment = state.appointments.find(a => a.id === action.payload.id);
      if (appointment) {
        appointment.status = action.payload.status;
        appointment.updatedAt = new Date().toISOString();
      }
    },

    // Add note to appointment
    addAppointmentNote: (state, action: PayloadAction<{ id: string; note: string }>) => {
      const appointment = state.appointments.find(a => a.id === action.payload.id);
      if (appointment) {
        appointment.notes = action.payload.note;
      }
    },

    // Clear error
    clearError: (state) => {
      state.error = null;
    },

    // Reset entire state
    resetAppointmentState: () => initialState,
  },

  // ============================================
  // EXTRA REDUCERS (Async)
  // ============================================
  extraReducers: (builder) => {
    builder
      // Fetch Appointments
      .addCase(fetchAppointments.pending, (state) => {
        state.isLoading = true;
        state.error = null;
      })
      .addCase(fetchAppointments.fulfilled, (state, action) => {
        state.isLoading = false;
        state.appointments = action.payload.appointments;
        state.pagination = action.payload.pagination;
        
        // Calculate stats
        state.stats.total = action.payload.pagination.total;
        state.stats.scheduled = state.appointments.filter(a => a.status === 'scheduled').length;
        state.stats.completed = state.appointments.filter(a => a.status === 'completed').length;
        state.stats.cancelled = state.appointments.filter(a => a.status === 'cancelled').length;
        state.stats.todayCount = state.appointments.filter(a => {
          const today = new Date().toDateString();
          return new Date(a.date).toDateString() === today;
        }).length;
      })
      .addCase(fetchAppointments.rejected, (state, action) => {
        state.isLoading = false;
        state.error = action.payload as string;
      })

      // Book Appointment
      .addCase(bookAppointment.pending, (state) => {
        state.isLoading = true;
        state.error = null;
      })
      .addCase(bookAppointment.fulfilled, (state, action) => {
        state.isLoading = false;
        state.appointments.unshift(action.payload);
        state.stats.total += 1;
        state.stats.scheduled += 1;
      })
      .addCase(bookAppointment.rejected, (state, action) => {
        state.isLoading = false;
        state.error = action.payload as string;
      })

      // Cancel Appointment
      .addCase(cancelAppointment.pending, (state) => {
        state.isLoading = true;
      })
      .addCase(cancelAppointment.fulfilled, (state, action) => {
        state.isLoading = false;
        const appointment = state.appointments.find(a => a.id === action.payload);
        if (appointment) {
          appointment.status = 'cancelled';
          appointment.updatedAt = new Date().toISOString();
          state.stats.scheduled = Math.max(0, state.stats.scheduled - 1);
          state.stats.cancelled += 1;
        }
      })
      .addCase(cancelAppointment.rejected, (state, action) => {
        state.isLoading = false;
        state.error = action.payload as string;
      })

      // Reschedule Appointment
      .addCase(rescheduleAppointment.pending, (state) => {
        state.isLoading = true;
      })
      .addCase(rescheduleAppointment.fulfilled, (state, action) => {
        state.isLoading = false;
        const appointment = state.appointments.find(a => a.id === action.payload.id);
        if (appointment) {
          appointment.date = action.payload.date;
          appointment.time = action.payload.time;
          appointment.updatedAt = new Date().toISOString();
        }
      })
      .addCase(rescheduleAppointment.rejected, (state, action) => {
        state.isLoading = false;
        state.error = action.payload as string;
      });
  },
});

// ============================================
// ACTIONS
// ============================================

export const {
  setSelectedAppointment,
  clearSelectedAppointment,
  setFilters,
  resetFilters,
  setPage,
  updateAppointmentStatus,
  addAppointmentNote,
  clearError,
  resetAppointmentState,
} = appointmentSlice.actions;

// ============================================
// SELECTORS
// ============================================

export const selectAllAppointments = (state: { appointments: AppointmentState }) => state.appointments.appointments;
export const selectSelectedAppointment = (state: { appointments: AppointmentState }) => state.appointments.selectedAppointment;
export const selectAppointmentLoading = (state: { appointments: AppointmentState }) => state.appointments.isLoading;
export const selectAppointmentError = (state: { appointments: AppointmentState }) => state.appointments.error;
export const selectAppointmentFilters = (state: { appointments: AppointmentState }) => state.appointments.filters;
export const selectAppointmentStats = (state: { appointments: AppointmentState }) => state.appointments.stats;
export const selectAppointmentPagination = (state: { appointments: AppointmentState }) => state.appointments.pagination;

export const selectTodayAppointments = (state: { appointments: AppointmentState }) => {
  const today = new Date().toDateString();
  return state.appointments.appointments.filter(a => new Date(a.date).toDateString() === today);
};

export const selectUpcomingAppointments = (state: { appointments: AppointmentState }) => {
  const now = new Date();
  return state.appointments.appointments.filter(a => {
    const appDate = new Date(`${a.date}T${a.time}`);
    return appDate > now && a.status !== 'cancelled';
  });
};

export const selectFilteredAppointments = (state: { appointments: AppointmentState }) => {
  const { appointments, filters } = state.appointments;
  
  return appointments.filter(app => {
    const statusMatch = filters.status === 'all' || app.status === filters.status;
    const typeMatch = filters.type === 'all' || app.type === filters.type;
    const searchMatch = !filters.search || 
      app.doctorName.toLowerCase().includes(filters.search.toLowerCase()) ||
      app.patientName.toLowerCase().includes(filters.search.toLowerCase()) ||
      app.hospitalName.toLowerCase().includes(filters.search.toLowerCase());
    
    return statusMatch && typeMatch && searchMatch;
  });
};

// ============================================
// REDUCER
// ============================================

export default appointmentSlice.reducer;

