                  className="w-full px-4 py-3 bg-white/[0.03] border border-white/[0.06] rounded-xl text-white text-sm placeholder-white/20 focus:outline-none focus:border-white/15 transition-all resize-none h-20" />
              </div>
            </motion.div>
          )}

