      } ${darkMode ? 'bg-gray-900 border-gray-800' : 'bg-white border-gray-200'} border-r shadow-2xl z-40`}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
